public display int headerPriceAttributeGroupSelectionPriority()
{
    UPSPriceComponentCodePriceAttributeGroupSelection selection;

    select Priority from selection where
            selection.PriceAttributeGroup == this.HeaderPriceAttributeGroup
                && selection.PriceComponentCode == this.PriceComponentCode;

    return selection.Priority;
}

public display int linePriceAttributeGroupSelectionPriority()
{
    UPSPriceComponentCodePriceAttributeGroupSelection selection;

    select Priority from selection where
            selection.PriceAttributeGroup == this.LinePriceAttributeGroup
                && selection.PriceComponentCode == this.PriceComponentCode;

    return selection.Priority;
}

internal boolean checkSourceLevel()
{
    boolean ret = true;

    if (this.HeaderGroupAll == UPSGroupAll::Group && this.HeaderPriceAttributeGroup)
    {
        UPSPricingAttributeGroup headerGroup = UPSPricingAttributeGroup::find(this.HeaderPriceAttributeGroup);
        if (headerGroup.SourceLevel != UPSPricingAttributeSourceLevel::Header)
        {
            ret = checkFailed("@UnifiedPricingService:SourceLevelNotMatchedError");
        }
    }

    if (this.LineGroupAll == UPSGroupAll::Group && this.LinePriceAttributeGroup)
    {
        UPSPricingAttributeGroup lineGroup = UPSPricingAttributeGroup::find(this.LinePriceAttributeGroup);
        if (lineGroup.SourceLevel != UPSPricingAttributeSourceLevel::Line)
        {
            ret = checkFailed("@UnifiedPricingService:SourceLevelNotMatchedError");
        }
    }

    return ret;
}

internal boolean checkPriority()
{
    boolean ret = true;

    if (this.Priority < 0)
    {
        ret = checkFailed("@UnifiedPricingService:CombinationPriorityOutOfRangeError");
    }

    return ret;
}

internal boolean checkInvalidAttributeGroup()
{
    boolean ret = true;

    if ((this.HeaderGroupAll == UPSGroupAll::Group && !this.HeaderPriceAttributeGroup) ||
        (this.HeaderGroupAll == UPSGroupAll::All   &&  this.HeaderPriceAttributeGroup))
    {
        ret = checkFailed("@UnifiedPricingService:UPSPriceComponentCodeCombinationHeaderGroupAllInvalid");
    }

    if ((this.LineGroupAll == UPSGroupAll::Group && !this.LinePriceAttributeGroup) ||
        (this.LineGroupAll == UPSGroupAll::All   &&  this.LinePriceAttributeGroup))
    {
        ret = checkFailed("@UnifiedPricingService:UPSPriceComponentCodeCombinationLineGroupAllInvalid");
    }

    return ret;
}

internal boolean checkGroupAll()
{
    boolean ret = true;

    if (this.HeaderGroupAll == UPSGroupAll::All || this.LineGroupAll == UPSGroupAll::All)
    {
        UPSPriceComponentCode priceComponentCode = UPSPriceComponentCode::find(this.PriceComponentCode);

        if (this.HeaderGroupAll == UPSGroupAll::All && priceComponentCode.HeaderPriceAttributeGroupAllEnabled == NoYes::No)
        {
            ret = checkFailed("@UnifiedPricingService:UPSPriceComponentCodeCombinationHeaderAllNotEnabled");
        }

        if (this.LineGroupAll == UPSGroupAll::All && priceComponentCode.LinePriceAttributeGroupAllEnabled == NoYes::No)
        {
            ret = checkFailed("@UnifiedPricingService:UPSPriceComponentCodeCombinationLineAllNotEnabled");
        }
    }

    return ret;
}

public boolean validateWrite()
{
    boolean ret = super();

    ret = ret && this.checkPriority();
    ret = ret && this.checkInvalidAttributeGroup();
    ret = ret && this.checkSourceLevel();
    ret = ret && this.checkGroupAll();

    return ret;
}

public void initPriority(UPSPriceComponentCodePriceAttributeGroupSelection _updatingSelection = null)
{
    int newPriority = 0;

    if (_updatingSelection && _updatingSelection.SourceLevel == UPSPricingAttributeSourceLevel::Header)
    {
        newPriority += 1000 * _updatingSelection.Priority;
    }
    else if (this.HeaderGroupAll == UPSGroupAll::Group)
    {
        UPSPriceComponentCodePriceAttributeGroupSelection selection;

        select Priority from selection where 
            selection.PriceAttributeGroup == this.HeaderPriceAttributeGroup
                && selection.PriceComponentCode == this.PriceComponentCode;

        newPriority += 1000 * selection.Priority;
    }

    if (_updatingSelection && _updatingSelection.SourceLevel == UPSPricingAttributeSourceLevel::Line)
    {
        newPriority += _updatingSelection.Priority;
    }
    else if (this.LineGroupAll == UPSGroupAll::Group)
    {
        UPSPriceComponentCodePriceAttributeGroupSelection selection;

        select Priority from selection where
            selection.PriceAttributeGroup == this.LinePriceAttributeGroup
                && selection.PriceComponentCode == this.PriceComponentCode;

        newPriority += selection.Priority;
    }

    this.Priority = newPriority;
}

public void insert()
{
    if (UPSPriceComponentCode::find(this.PriceComponentCode).MaintenanceMode == UPSPriceComponentCodeMaintenanceMode::Separate)
    {
        this.initPriority();
    }

    super();
}
